CATEGORIES = [
    {"id": "runtime", "title": "Runtime & JavaScript", "color": "sky", "blurb": "Event loop, modules, promises and asynchronous errors."},
    {"id": "apis", "title": "APIs & Data Flow", "color": "mint", "blurb": "HTTP services, streams, validation and backpressure."},
    {"id": "tooling", "title": "Packages & Testing", "color": "lilac", "blurb": "npm, lockfiles, testing and supply-chain safety."},
    {"id": "production", "title": "Production Operations", "color": "peach", "blurb": "Configuration, observability, profiling and deployment."},
]

TOPICS = build_lessons([
    ("node-runtime", "Node.js Runtime, V8 & libuv", "runtime", "basic", "Node.js runs JavaScript on V8 and uses libuv to coordinate the event loop, timers, networking and selected worker-pool operations. Most I/O is asynchronous; CPU-heavy synchronous JavaScript still blocks the event loop.", "node --version && node --trace-warnings app.js", "The runtime version and platform affect APIs, performance and dependency compatibility; pin a supported LTS line.", "Does asynchronous I/O mean CPU-heavy JavaScript runs in parallel?", "No. CPU-heavy JavaScript on the main event loop blocks other callbacks. Use worker threads or separate processes for CPU-bound work.", ["node-event-loop", "node-worker-threads"]),
    ("node-event-loop", "Event Loop, Tasks & Microtasks", "runtime", "intermediate", "The event loop coordinates callbacks, timers, I/O and microtasks. Promise callbacks and queueMicrotask run as microtasks; recursive microtask scheduling can starve timers and I/O callbacks.", "Measure event-loop delay while load and CPU work are active", "Do not assume setTimeout(0) runs immediately or that all callback queues have identical ordering.", "Why can a timer run late even when configured for 10 ms?", "The timer becomes eligible after the delay, but the runtime runs it only when the current JavaScript and higher-priority queued work allow it.", ["node-promises", "node-performance"]),
    ("node-modules", "CommonJS, ES Modules & Package Boundaries", "runtime", "basic", "Node supports CommonJS require/module.exports and ECMAScript import/export. Package type, file extensions, exports maps and interop determine how modules load and which paths consumers can access.", "Set package.json type to module and use explicit .js imports consistently", "Mixing module systems requires deliberate interop; hidden deep imports can break when a package exports map is added.", "How does Node decide whether a .js file is CommonJS or ESM?", "It considers the nearest package.json type field and file extension. .mjs is ESM and .cjs is CommonJS regardless of package type.", ["node-package-json", "node-typescript"]),
    ("node-promises", "Promises, async/await & Error Propagation", "runtime", "intermediate", "Promises represent eventual fulfillment or rejection. async/await makes promise chains easier to read, but rejected promises still need to be awaited, returned or handled to reach the intended error boundary.", "try { return await loadRecord(id); } catch (err) { next(err); }", "An unawaited promise can reject after the caller has returned, losing error context and cleanup.", "What happens if an async function rejects and its promise is not awaited?", "The rejection can become unhandled and may bypass the request's error handling. Return or await the promise and route failures through one explicit boundary.", ["node-event-loop", "node-abort-signal"]),
    ("node-abort-signal", "Cancellation, Timeouts & AbortController", "runtime", "intermediate", "AbortController provides a standard cancellation signal for fetch and many Node APIs. Timeouts should cancel the underlying operation where possible, not merely stop waiting for its result.", "const c = new AbortController(); setTimeout(() => c.abort(), 2000); await fetch(url, { signal: c.signal });", "A timeout that leaves network or database work running can consume sockets and capacity after the caller has given up.", "Why is Promise.race with a timeout alone insufficient?", "It rejects the waiting promise but does not cancel the underlying operation. Pass an AbortSignal or use the dependency's cancellation mechanism.", ["node-promises", "node-http"]),
    ("node-http", "HTTP Servers, Routing & Middleware", "apis", "basic", "Node's HTTP server exposes request and response streams. Framework middleware should validate input, enforce timeouts/body limits and provide one consistent error boundary.", "Create the server once, use a router, and set request/header/body limits", "Do not perform expensive synchronous work or unbounded body buffering in a request handler.", "What can happen when an API buffers an unbounded request body?", "A client can exhaust process memory or event-loop capacity. Enforce body limits, stream large payloads and apply request deadlines.", ["node-streams", "node-security"]),
    ("node-streams", "Streams, Backpressure & Pipeline", "apis", "intermediate", "Streams process data incrementally. Writable backpressure is signaled when write returns false; producers should wait for drain or use pipeline(), which propagates errors and handles cleanup.", "await pipeline(createReadStream(src), transform, createWriteStream(dst))", "Ignoring backpressure turns a fast producer and slow consumer into unbounded memory growth.", "What should a producer do when writable.write() returns false?", "Pause production until the writable emits drain, or use stream.pipeline/async iteration which coordinates flow and errors.", ["node-http", "node-performance"]),
    ("node-worker-threads", "Worker Threads & CPU-Bound Work", "runtime", "advanced", "Worker threads run JavaScript in separate isolates and can use message passing or shared memory. They help CPU-bound tasks but add scheduling, serialization and lifecycle costs.", "Use a bounded worker pool for image transforms or expensive computation", "A worker per request can exhaust resources; use a bounded pool with queue limits and cancellation.", "When should a Node service use worker threads?", "For CPU-bound JavaScript that would otherwise block the event loop. They are usually unnecessary for ordinary asynchronous network or file I/O.", ["node-event-loop", "node-performance"]),
    ("node-package-json", "npm, package.json & Lockfiles", "tooling", "basic", "package.json declares scripts and dependency ranges; a lockfile captures resolved package versions and integrity metadata. npm ci installs from the lockfile and fails if it disagrees with package.json.", "npm ci --ignore-scripts  # in an untrusted dependency inspection workflow", "Commit the lockfile for applications, review lifecycle scripts and update dependencies with an auditable toolchain.", "Why does CI commonly use npm ci instead of npm install?", "npm ci performs a clean, lockfile-driven install and fails on manifest/lock mismatch, making builds more repeatable than resolving ranges during every run.", ["node-supply-chain", "node-testing"]),
    ("node-supply-chain", "Dependency Audits & npm Supply Chain", "tooling", "advanced", "Dependency security includes transitive packages, install scripts, registry identity, lockfile integrity and maintainer changes. Audit advisories, pin trusted registries and protect tokens and publish workflows.", "npm audit --omit=dev · generate an SBOM · use provenance for published packages", "Do not blindly run every suggested upgrade; assess exploitability, compatibility and the dependency path, then patch and verify.", "What does a lockfile protect against, and what does it not protect against?", "It records exact dependency resolutions and integrity, improving repeatability. It does not prove a package is benign or eliminate vulnerabilities in a pinned dependency.", ["node-package-json", "node-testing"]),
    ("node-testing", "Unit, Integration & Node Test Runner", "tooling", "intermediate", "Node's built-in test runner and third-party frameworks support unit and integration tests. Isolate external services, control timers and environment, and test observable behavior including rejection and cancellation paths.", "node --test", "A passing unit suite does not prove routes, databases and auth providers integrate correctly; add contract and integration coverage at boundaries.", "How do you keep a Node test from leaking a server handle?", "Close the server and clients in teardown hooks, await async cleanup and ensure timers/worker pools are stopped even when assertions fail.", ["node-http", "node-promises"]),
    ("node-validation", "Input Validation, Serialization & Security", "apis", "intermediate", "Validate untrusted input against a schema at the boundary and serialize output intentionally. Avoid prototype pollution, unsafe dynamic property assignment, injection and leaking internal error objects.", "Parse request JSON with a schema that bounds string lengths and rejects unexpected fields", "Validate authorization separately from shape: a valid resource ID does not prove the caller owns that resource.", "Why should an API reject unexpected fields instead of silently accepting them?", "Strict schemas catch client mistakes and mass-assignment attempts, and make contract changes explicit. Some public APIs may choose forward compatibility, but sensitive write paths need clear allow-lists.", ["node-http", "node-security"]),
    ("node-security", "Node.js Security: SSRF, Injection & Secrets", "apis", "advanced", "Node services need safe URL allowlists, DNS/IP validation for outbound requests, parameterized database queries, secure cookies, rate limits and secret handling. Block cloud metadata and private ranges where user-controlled fetches exist.", "Allowlist trusted hostnames, resolve and validate all IPs, and recheck redirects", "Checking a hostname once is insufficient against DNS rebinding and redirect-based SSRF.", "How can a user-controlled URL lead to SSRF?", "The server may fetch internal services or metadata endpoints using its own network access. Validate resolved addresses, restrict egress and recheck redirect targets.", ["node-validation", "node-supply-chain"]),
    ("node-logging", "Structured Logs, Metrics & Traces", "production", "intermediate", "Structured logs carry fields such as request ID, route, status and duration. Metrics expose rates, errors and latency; traces connect work across dependencies. Avoid logging tokens, passwords and personal data.", "Emit request_id, trace_id, service, route, duration_ms and status_code", "Instrument high-value service boundaries and keep metric labels bounded; user IDs and raw URLs create cardinality and privacy risks.", "Why not use a unique request ID as a Prometheus label?", "Each unique label value creates a time series, causing unbounded cardinality and memory/storage cost. Put unique IDs in logs or traces instead.", ["node-http", "node-performance"]),
    ("node-config", "Environment Configuration & Runtime Validation", "production", "intermediate", "Environment variables and secret stores configure deployments. Validate required settings once at startup, fail fast on invalid values and avoid leaking secret contents in errors.", "Parse PORT as a bounded integer; validate DATABASE_URL before accepting traffic", "A default that silently points production to a test service can be more dangerous than a clear startup failure.", "Why validate configuration at startup?", "It catches missing or malformed values before requests arrive and provides a clear operator error instead of intermittent runtime failures.", ["node-security", "node-http"]),
    ("node-performance", "Profiling, Event-Loop Delay & Memory", "production", "advanced", "Profile CPU, heap and event-loop delay under representative load. Memory may grow from retained closures, buffers, listeners or unbounded caches; compare heap snapshots and inspect GC before guessing.", "Use node --cpu-prof or the inspector; monitor event-loop delay and heap after warm-up", "Profile realistic traffic and compare one controlled change; avoid optimizing synthetic microbenchmarks that do not match the service.", "What does sustained event-loop delay usually indicate?", "The main thread is blocked or overburdened by CPU work, synchronous I/O or excessive callback/microtask work. Profile the hot path and move CPU-bound work to a bounded worker pool where appropriate.", ["node-worker-threads", "node-logging"]),
    ("node-graceful-shutdown", "Graceful Shutdown & Deployment Lifecycle", "production", "advanced", "A production service should stop accepting new work on SIGTERM, drain in-flight requests within a deadline, close database and message clients, and exit. Kubernetes termination grace periods must exceed the app's drain budget.", "SIGTERM → stop listener → await in-flight requests → close dependencies → exit", "Force-kill after a bounded deadline; leave enough time for the orchestrator and load balancer to remove the instance.", "Why is process.exit() immediately inside a SIGTERM handler risky?", "It can cut off in-flight responses, logs and cleanup. Stop accepting traffic, drain work and close resources before exiting, with a hard deadline for stuck work.", ["node-http", "node-config"]),
    ("node-deployment", "Node.js Containers & Production Images", "production", "intermediate", "A production image should use a supported base, install from the lockfile, include only runtime dependencies and run as a non-root user. Keep the app stateless and configure health, termination and resource limits.", "npm ci --omit=dev && node server.js", "Pin a base image digest in high-assurance builds and scan the final image, not only the source package manifest.", "Why should the final container image be scanned?", "The image includes the actual base OS, runtime and installed packages that ship. Source-level dependency checks miss operating-system packages and build output contents.", ["node-package-json", "node-supply-chain", "node-graceful-shutdown"]),
    ("node-typescript", "TypeScript in Node Services", "tooling", "intermediate", "TypeScript checks types before runtime but does not validate JSON or network input at runtime. Module resolution, build output and source maps must match the deployed Node version and module system.", "Compile with strict settings; validate request data at runtime with a schema", "A TypeScript type assertion is removed at compile time and cannot make untrusted input safe.", "Does `payload as User` validate a request body?", "No. It only changes the compiler's view; it performs no runtime check. Parse and validate the data before using it as a User.", ["node-modules", "node-validation"]),
], "NODE", "A Node.js service responds to events by using asynchronous work and keeping each request within a bounded lifecycle.")

